const b = $input.first().json.body || $input.first().json;
const name = b.name || 'друг';
const contact = b.contact || '';
const projectUrl = b.project || b.url || b.projectUrl || '';
const form = b.form || '';
const chatId = (contact || '').replace('@', '').trim();

const entryBonus = {
  'Запустить спринт': 4,
  'Обсудить проект': 3,
  'Запустим ваш проект': 3,
  'Заказать аудит': 2,
  'Бесплатный аудит': 1,
  'Расскажите о вашей идее': 1
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.users) staticData.users = {};
staticData.users[chatId] = {
  name,
  contact,
  projectUrl,
  formSource: form,
  chatId,
  ts: new Date().toISOString(),
  step: 0,
  leadScore: entryBonus[form] || 1
};

return [{ json: { chatId, name, projectUrl } }];

