const d = $input.first().json;
const scores = { yes: 5, maybe: 3, no: 0 };
const staticData = $getWorkflowStaticData('global');
const user = (staticData.users || {})[d.chatId] || {};

user.readiness = d.value;
user.step = 6;
user.leadScore = (user.leadScore || 0) + (scores[d.value] || 0);

if (user.leadScore >= 18) user.leadType = 'hot';
else if (user.leadScore >= 10) user.leadType = 'warm';
else user.leadType = 'cold';

if (staticData.users) staticData.users[d.chatId] = user;

return [{ json: { ...user, chatId: d.chatId, hasUrl: !!user.projectUrl } }];

const d = $input.first().json;
const text = d.data?.text || d.text || '';
const urlMatch = text.match(/(https?:\/\/[^\s]+)/i);
let projectUrl = urlMatch ? urlMatch[1] : text.trim();
if (projectUrl && !projectUrl.startsWith('http')) projectUrl = 'https://' + projectUrl;

const staticData = $getWorkflowStaticData('global');
const chatId = d.chatId || '';
