user.projectUrl = projectUrl;
if (staticData.users) staticData.users[chatId] = user;

return [{ json: { ...user, chatId, projectUrl } }];

const d = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const user = (staticData.users || {})[d.chatId] || d;

const goalMap = { leads: '📈 Больше заявок', convert: '🤔 Не конвертит', redesign: '🎨 Редизайн', curious: '👀 Интересно' };
const nicheMap = { ecom: '🛍 E-commerce', b2b: '💼 Услуги/B2B', edu: '🎓 Обучение', med: '🏥 Медицина', horeca: '🍔 HoReCa', it: '💻 IT/SaaS', other: '🔧 Другое' };
const audMap = { b2c: '👤 B2C', b2b: '🏢 B2B', both: '👤+🏢 Оба', unsure: '🤷 Определяется' };
const trafficMap = { low: '🌱 <500', mid: '📈 500-5к', high: '🚀 5к-50к', mega: '🔥 50к+' };
const stageMap = { startup: '🚀 Запуск', growth: '📊 Рост', scale: '🏢 Масштаб' };
const readyMap = { yes: '✅ Да', maybe: '🤔 Зависит', no: '👀 Смотрит' };
const leadMap = { hot: '🔥 HOT', warm: '🟡 WARM', cold: '🔵 COLD' };

const focusMap = {
  leads: 'Анализ CTA-элементов, форм захвата, пути до конверсии',
  convert: 'Первый экран, ясность УТП, факторы доверия, барьеры конверсии',
  redesign: 'Визуальная современность, UI-паттерны, UX-flow',
  curious: 'Общий обзор всех аспектов с приоритизацией по потенциалу роста'
};

const msg = '🆕 <b>Новая заявка на аудит!</b>\n\n' +
  '👤 <b>Клиент:</b> ' + (user.name || 'N/A') + '\n' +
  '📱 <b>Chat ID:</b> ' + d.chatId + '\n' +
  '🌐 <b>Сайт:</b> ' + (user.projectUrl || d.projectUrl || 'N/A') + '\n\n' +
  '📋 <b>Профиль:</b>\n' +
  '• Цель: ' + (goalMap[user.goal] || 'N/A') + '\n' +
  '• Ниша: ' + (nicheMap[user.niche] || 'N/A') + '\n' +
  '• Аудитория: ' + (audMap[user.audience] || 'N/A') + '\n' +
  '• Трафик: ' + (trafficMap[user.traffic] || 'N/A') + '\n' +
  '• Стадия: ' + (stageMap[user.stage] || 'N/A') + '\n' +
  '• Готовность: ' + (readyMap[user.readiness] || 'N/A') + '\n\n' +
  (leadMap[user.leadType] || '🔵 COLD') + ' <b>Тип лида</b> (' + (user.leadScore || 0) + '/24)';

const nicheLabel = nicheMap[user.niche] || 'не указана';
const audLabel = audMap[user.audience] || 'не указана';
const goalLabel = goalMap[user.goal] || 'не указана';
const trafficLabel = trafficMap[user.traffic] || 'не указан';
const stageLabel = stageMap[user.stage] || 'не указана';
const readyLabel = readyMap[user.readiness] || 'не указана';
const focusArea = focusMap[user.goal] || focusMap.curious;

return [{ json: {
  chatId: d.chatId,
  projectUrl: user.projectUrl || d.projectUrl,
  name: user.name,
  leadType: user.leadType,
  leadScore: user.leadScore,
  ownerMsg: msg,
  nicheLabel, audLabel, goalLabel, trafficLabel, stageLabel, readyLabel, focusArea
} }];

const prev = $('Данные для владельца').first().json;
const r = $input.first().json;
const txt = r.content?.[0]?.text || '';

let auditData;
try {
  auditData = JSON.parse(txt);
} catch(e) {
  const m = txt.match(/\{[\s\S]*\}/);
  auditData = m ? JSON.parse(m[0]) : {
    overall_score: 5.0, total_potential: '+50% CR',
    executive_summary: 'Требуется детальный анализ.',
    scores: [{label:'Первый экран',score:5,comment:''},{label:'Ясность предложения',score:5,comment:''},{label:'CTA и формы',score:5,comment:''},{label:'Доверие',score:5,comment:''},{label:'Мобильная версия',score:5,comment:''}],
    issues: [],
    quick_wins: ['Проверить скорость загрузки','Добавить чёткий CTA','Добавить отзывы клиентов']
  };
}

while ((auditData.issues || []).length < 5) {
  auditData.issues = auditData.issues || [];
  auditData.issues.push({ number: auditData.issues.length+1, title:'Требует анализа', problem:'Необходимо детальное изучение.', hypothesis:'Улучшение повысит конверсию.', solution:'Углублённый анализ.', priority:'средний', complexity:'средняя', potential:'+10% CR', comment:'' });
}
if (!auditData.quick_wins || auditData.quick_wins.length < 3) {
  auditData.quick_wins = auditData.quick_wins || [];
  while (auditData.quick_wins.length < 3) auditData.quick_wins.push('Провести аудит скорости загрузки');
}

return [{ json: { chatId: prev.chatId, projectUrl: prev.projectUrl, name: prev.name, leadType: prev.leadType, leadScore: prev.leadScore, auditData, nicheLabel: prev.nicheLabel, audLabel: prev.audLabel, goalLabel: prev.goalLabel, trafficLabel: prev.trafficLabel, stageLabel: prev.stageLabel, focusArea: prev.focusArea } }];
